#!/usr/bin/env node
/* eslint-disable no-console */

const cds = require('@sap/cds')
const { _import, isfile, local, path } = cds.utils

async function run(param, options) {
    const { dry, genTenantList, syncTenantList, cleanup, directory, tag, tagRule } = options
    const skipVerification = options['skip-verification'] || options.skipVerification

    function _handleError(message) {
        console.log(message)
        process.exit(1)
    }

    // Check for removed migration options
    const removedOptions = []
    if (cleanup) removedOptions.push('--cleanup')
    if (directory) removedOptions.push('--directory')
    if (tag) removedOptions.push('--tag')
    if (tagRule) removedOptions.push('--tagRule')
    if (skipVerification) removedOptions.push('--skip-verification')

    if (removedOptions.length) {
        _handleError(`The option(s) ${removedOptions.join(', ')} are no longer supported. The migration from @sap/cds-mtx to @sap/cds-mtxs has been removed.`)
    }

    if (!genTenantList && !syncTenantList) {
        _handleError(`The migration from @sap/cds-mtx to @sap/cds-mtxs has been removed. Only --init-tenant-list and --sync-tenant-list are still supported.`)
    }

    const { syncTenantList: synchronizeTenantList, _hasMtEnv } = require('../lib/migration/migration')

    async function cds_mtx_migrate(tenants, options) {
        if (!_hasMtEnv()) _handleError(`cds-mtx-migrate operation can only be run inside a multitenant application environment using @sap/cds-mtxs.`)
        if (!tenants) _handleError(`Please provide tenant(s): cds-mtx-migrate <tenant>[,<tenant>]`)

        const tenantList = _splitTenants(tenants)

        const services = [
            '@sap/cds/srv/mtx',
            '@sap/cds-mtxs/srv/model-provider'
        ]

        if (!dry) {
            services.push('@sap/cds-mtxs/srv/deployment-service')
            services.push('@sap/cds-mtxs/srv/extensibility-service')
        }

        await _local_server_js()
        cds.emit ('bootstrap')
        const model = await cds.load([...services, '@sap/cds-mtxs/db/extensions'])
        cds.model = cds.compile.for.nodejs(model)
        const d = 'cds.xt.DeploymentService'
        const unserved = !cds.services[d]
        if (unserved) {
            await cds.serve(services)
        }
        await cds.plugins

        await cds.emit('served', cds.services)

        cds.env.requires.multitenancy ??= true // needed for current sidecar config that only enables services

        if (genTenantList) {
            const tenantListResult = await synchronizeTenantList(tenantList, options)
            for (let t of tenantListResult.connectedTenants) await cds.db.disconnect(t)
            await cds.db.disconnect()

            tenantListResult.logResult(dry)
        } else if (syncTenantList) {
            const tenantListResult = await synchronizeTenantList(tenantList, options, true)
            for (let t of tenantListResult.connectedTenants) await cds.db.disconnect(t)
            await cds.db.disconnect()

            tenantListResult.logResult(dry)
        }
    }

    function _splitTenants(tenants) {
        return tenants.split(',')
    }

    await cds_mtx_migrate(param, options).catch(console.error)
}

// copied from cds.serve
async function _local_server_js() {
    const _local = file => isfile(file) || isfile (path.join(cds.env.folders.srv,file))
    const cli_js = process.env.CDS_TYPESCRIPT && _local('cli.ts') || _local('cli.js')
    if (cli_js) {
      console.log ('[cds] - loading server from', { file: local(cli_js) })
      await _import(cli_js)
    }
  }

function getParameterValue(options, parameter) {
   const index = options.indexOf(parameter)
   const value = (index > -1) ? options[index + 1] : undefined
   return value && value[0] !== '-' ? value : undefined
}

if (require.main === module) {
   // Code section that will run only if current file is the entry point.
   // TODO use command line parser to get arguments
   // comma separated list of tenants
   const [, , tenants, ...options] = process.argv
   const dry = options.includes('--dry')
   const genTenantList = options.includes('--init-tenant-list')
   const syncTenantList = options.includes('--sync-tenant-list')
   const force = options.includes('--force')
   const cleanup = options.includes('--cleanup')
   const skipVerification = options.includes('--skip-verification')
   const directory = getParameterValue(options, '-d') || getParameterValue(options, '--directory')
   const tag = getParameterValue(options, '--tag')
   const tagRule = getParameterValue(options, '--tagRule')
   run(tenants, { dry, force, genTenantList, syncTenantList, cleanup, directory, tag, tagRule, 'skip-verification': skipVerification }).catch(console.error)
} else {
     module.exports.run = run
}
